import torch
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------
# Inline CUDA + C++ source implementing 1D average pooling (fp16)
# --------------------------------------------------------------------
src = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void avg_pool1d_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    int batch,
    int channels,
    int input_len,
    int output_len,
    int kernel,
    int stride,
    int padding) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * channels * output_len;
    if (idx >= total) return;

    // decode linear index to (b, c, o)
    int o = idx % output_len;
    int tmp = idx / output_len;
    int c = tmp % channels;
    int b = tmp / channels;

    int start = o * stride - padding;
    int end   = start + kernel;

    int sum_start = max(start, 0);
    int sum_end   = min(end, input_len);
    int count = sum_end - sum_start;

    float sum = 0.0f;
    if (count > 0) {
        const scalar_t* in_ptr = input + ((b * channels + c) * input_len);
        for (int i = sum_start; i < sum_end; ++i) {
            sum += static_cast<float>(in_ptr[i]);
        }
    }
    float avg = (count > 0) ? sum / static_cast<float>(count) : 0.0f;
    output[idx] = static_cast<scalar_t>(avg);
}

torch::Tensor avg_pool1d_cuda(torch::Tensor input,
                              int kernel,
                              int stride,
                              int padding) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");

    int batch      = input.size(0);
    int channels   = input.size(1);
    int input_len  = input.size(2);
    int output_len = (input_len + 2 * padding - kernel) / stride + 1;

    auto opts = torch::TensorOptions().dtype(torch::kHalf).device(input.device());
    torch::Tensor output = torch::empty({batch, channels, output_len}, opts);

    int total = batch * channels * output_len;
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "avg_pool1d_cuda", ([&] {
        avg_pool1d_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch,
            channels,
            input_len,
            output_len,
            kernel,
            stride,
            padding);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("avg_pool1d", &avg_pool1d_cuda, "1D average pooling (CUDA, fp16)");
}
"""

# Compile the extension inline
avgpool_ext = load_inline(name="avgpool_ext",
                          cpp_sources=src,
                          functions=["avg_pool1d"],
                          verbose=False)

