        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is on CUDA and cast to fp16
        x = x.to(device='cuda', dtype=torch.float16)
